// Accepts the WordPress webhook (post id in the body) or the manual test. Outputs { post_id, client_id }.
const j = $input.first().json || {};
const b = (j.body && typeof j.body === 'object') ? j.body : j;
const raw = b.post_id ?? b.postId ?? b.ID ?? b.id ?? (b.post && (b.post.ID ?? b.post.id)) ?? '';
const post_id = String(raw).trim();
if (!/^[0-9]+$/.test(post_id)) {
  throw new Error('No WordPress post id: send {"post_id": 123} to the webhook (or fill "Test Post ID" for a manual test). Got: ' + JSON.stringify(raw));
}
return [{ json: { post_id, client_id: String(b.client_id || '').trim() } }];

// CEKIVA publishing: one POST /v1/posts per platform, each with the copy the AI wrote for THAT platform.
// X/Twitter is not here on purpose: CEKIVA retired that channel.
const CONFIG = {
  CLIENT_ID: '',      // optional: a CEKIVA client workspace (GET https://cekiva.com/api/v1/clients). The webhook can also send "client_id". Empty = your primary workspace.
  PUBLISH_NOW: true,  // true = publish right away; false = publish at SCHEDULED_AT
  SCHEDULED_AT: '',   // ISO 8601 with a time zone, e.g. 2026-12-01T09:00:00Z (used only when PUBLISH_NOW is false)
  APPEND_LINK: true,  // add the blog post's link to the copy (when it still fits the platform's length limit)
};
const LIMITS = { threads: 500, bluesky: 300 }; // other platforms: no practical limit here

const out = ($('Social Media Manager').first().json.output) || {};
const post = $('Get Post').first().json || {};
const link = post.link || '';
const meta = $('Featured image').first().json || {};
const body = meta.body && typeof meta.body === 'object' ? meta.body : meta;
const imageUrl = (typeof body.source_url === 'string' && /^https?:\/\//.test(body.source_url)) ? body.source_url : null;
const clientId = String($('Post ID').first().json.client_id || CONFIG.CLIENT_ID || '').trim();

// keys = CEKIVA platform ids; values = the AI's field for that platform
const copy = { facebook_page: out.facebook, instagram: out.instagram, linkedin: out.linkedin, threads: out.threads, bluesky: out.bluesky };
const scheduleAt = !CONFIG.PUBLISH_NOW && CONFIG.SCHEDULED_AT ? CONFIG.SCHEDULED_AT : null;

return Object.entries(copy)
  .filter(([, text]) => typeof text === 'string' && text.trim())
  .map(([platform, text]) => {
    let content = text.trim();
    const withLink = link && !content.includes(link) ? content + '\n\n' + link : content;
    // Instagram captions do not make links clickable, so the link is not added there.
    if (CONFIG.APPEND_LINK && platform !== 'instagram' && withLink.length <= (LIMITS[platform] || Infinity)) content = withLink;
    // The body of POST /v1/posts exactly as the CEKIVA API expects it.
    const request = { platforms: [platform], content, scheduled_for: scheduleAt || new Date().toISOString(), publish_now: !scheduleAt };
    if (imageUrl) { request.image_url = imageUrl; request.media_urls = [imageUrl]; } // Instagram needs an image: without one CEKIVA answers IMAGE_REQUIRED for that row
    if (clientId) request.client_id = clientId;
    return { json: { platform, request } };
  });

// One uniform result row per platform.
const sent = $('Build CEKIVA posts').all();
return $input.all().map((item, i) => {
  const r = item.json;
  const platform = sent[i] ? sent[i].json.platform : 'unknown';
  const body = r.body;
  const post = Array.isArray(body) ? body[0] : null;
  const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
  const status = Number(r.statusCode) || null;
  const ok = status !== null && status >= 200 && status < 300 && !!post;
  return { json: {
    platform,
    result: ok ? 'Success' : 'Error',
    http_status: status,
    post_id: post ? post.id : null,
    post_status: post ? post.status : null,
    credits_charged: post ? post.credits_charged : null,
    error_code: err ? err.code : (r.error ? 'CEKIVA_UNREACHABLE' : null),
    error_message: err ? err.message : (r.error ? String(r.error.message || r.error).slice(0, 200) : (ok ? null : 'Unexpected response')),
    hint: err ? err.hint : null,
  } };
});
